mapper.sql:
WHERE o.order_status = 'WAIT_USE'
AND ( o.order_no LIKE CONCAT('%', #{keyword}, '%') OR p.title LIKE CONCAT('%', #{keyword}, '%') OR s.station_name LIKE CONCAT('%', #{keyword}, '%') OR v.venue_name LIKE CONCAT('%', #{keyword}, '%') )
AND o.project_id = #{projectId}
AND o.session_id = #{sessionId}
AND o.create_time >= CONCAT(#{dateFrom}, ' 00:00:00')
AND o.create_time <= CONCAT(#{dateTo}, ' 23:59:59')

mapper.select:
SELECT COUNT(*) FROM ( SELECT o.order_id, AS issueStatus FROM ticket_order o LEFT JOIN performance_project p ON p.project_id = o.project_id LEFT JOIN performance_session s ON s.session_id = o.session_id LEFT JOIN venue v ON v.venue_id = s.venue_id LEFT JOIN electronic_ticket t ON t.order_id = o.order_id
GROUP BY o.order_id
HAVING issueStatus = #{issueStatus}
) issue_orders

SELECT o.order_id AS orderId, o.order_no AS orderNo, o.order_status AS orderStatus, o.pay_amount AS payAmount, o.project_id AS projectId, p.title AS projectTitle, o.session_id AS sessionId, s.city_name AS cityName, s.station_name AS stationName, v.venue_name AS venueName, s.start_time AS startTime, o.ticket_issued_time AS ticketIssuedTime, COUNT(t.ticket_id) AS totalTicketCount, SUM(CASE WHEN t.ticket_status = 'GENERATING' THEN 1 ELSE 0 END) AS generatingCount, SUM(CASE WHEN t.ticket_status = 'ERROR' THEN 1 ELSE 0 END) AS errorCount, SUM(CASE WHEN t.ticket_status = 'UNUSED' THEN 1 ELSE 0 END) AS unusedCount, SUM(CASE WHEN t.ticket_status = 'CHECKED' THEN 1 ELSE 0 END) AS checkedCount, SUM(CASE WHEN t.ticket_status = 'EXPIRED' THEN 1 ELSE 0 END) AS expiredCount, AS issueStatus, MIN(t.create_time) AS ticketCreateTime, MAX(t.update_time) AS ticketUpdateTime FROM ticket_order o LEFT JOIN performance_project p ON p.project_id = o.project_id LEFT JOIN performance_session s ON s.session_id = o.session_id LEFT JOIN venue v ON v.venue_id = s.venue_id LEFT JOIN electronic_ticket t ON t.order_id = o.order_id
GROUP BY o.order_id, o.order_no, o.order_status, o.pay_amount, o.project_id, p.title, o.session_id, s.city_name, s.station_name, v.venue_name, s.start_time, o.ticket_issued_time
HAVING issueStatus = #{issueStatus}
ORDER BY ticketUpdateTime DESC, o.order_id DESC LIMIT #{limit} OFFSET #{offset}

